import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import DangNhap from './trang/DangNhap';

// Import trang chủ Quản lý (nơi chứa Sidebar)
import TrangChuQuanLy from './trang/QuanLy/TrangChuQuanLy';

// Import các trang con trong folder QuanLy
import QuanLyCuDan from './trang/QuanLy/QuanLyCuDan';
import QuanLyCanHo from './trang/QuanLy/QuanLyCanHo';
// Sau này bạn tạo thêm file nào thì import thêm vào đây, ví dụ:
// import QuanLyHoaDon from './trang/QuanLy/QuanLyHoaDon';

// Dashboard Cư dân tạm thời (Giữ nguyên phần cũ của bạn)
const DashboardCuDan = () => (
  <div style={styles.dashboardContainer}>
    <h1 style={{ color: '#2e7d32' }}>🌳 DASHBOARD CƯ DÂN</h1>
    <p>Chào Cư dân! Chúc bạn một ngày tốt lành tại A&RMS.</p>
  </div>
);

function App() {
  return (
    <Router>
      <Routes>
        {/* 1. Mặc định vào trang sẽ đẩy sang đăng nhập */}
        <Route path="/" element={<Navigate to="/auth" />} />

        {/* 2. Trang Auth (Đăng nhập & Đăng ký) */}
        <Route path="/auth" element={<DangNhap />} />

        {/* 3. Phân luồng Dashboard QUẢN LÝ (Có các trang con lồng nhau) */}
        <Route path="/dashboard-quan-ly" element={<TrangChuQuanLy />}>
            {/* Khi mới đăng nhập vào Quản lý, tự động hiện trang Cư Dân */}
            <Route index element={<Navigate to="cu-dan" />} />

            {/* Các đường dẫn con tương ứng với Sidebar */}
            <Route path="cu-dan" element={<QuanLyCuDan />} />
            <Route path="can-ho" element={<QuanLyCanHo />} />

            {/* Bạn có thể thêm các route khác khi tạo xong file:
               <Route path="hoa-don" element={<QuanLyHoaDon />} /> 
            */}
        </Route>

        {/* 4. Dashboard CƯ DÂN (Giữ nguyên phần cũ) */}
        <Route path="/dashboard-cu-dan" element={<DashboardCuDan />} />

        {/* 5. Gõ sai địa chỉ sẽ về lại Đăng nhập */}
        <Route path="*" element={<Navigate to="/auth" />} />
      </Routes>
    </Router>
  );
}

const styles = {
  dashboardContainer: {
    display: 'flex', flexDirection: 'column', justifyContent: 'center', 
    alignItems: 'center', height: '100vh', textAlign: 'center', fontFamily: 'sans-serif'
  }
};

export default App;
